package pt.isel.pdm.droidmentor.domain // Groups the domain models.

/** Identifies the participant that authored a conversation message. */
enum class Role { // Lists the possible values for Role.
    /** A message written by the application user. */
    USER, // The person using the app wrote this message.

    /** A reply generated by the mentor model. */
    MODEL, // The mentor model generated this reply.
} // Ends this block.
